+.figure {
+  display: flex;
+  flex-direction: column;
+  gap: 10px;
+  min-width: 0;
+}
+
+/*
+ * 음영의 두 색을 여기 한 곳에서 정한다. SVG 안에서 `var(--result-shade-*)`로 읽으므로 테마 토큰이
+ * 바뀌어도 컴포넌트를 고치지 않는다.
+ */
+.chart {
+  --result-shade-fill: rgb(232 189 114 / 16%);
+  --result-shade-edge: rgb(232 189 114 / 78%);
+
+  width: 100%;
+  min-width: 0;
+  border: 1px solid var(--thorp-line);
+  border-radius: 14px;
+  background: var(--thorp-surface);
+
+  /* 넓은 화면에서는 납작하게, 좁은 화면에서는 세로를 키워 하락 구간이 눌리지 않게 한다. */
+  aspect-ratio: 16 / 7;
+}
+
+/*
+ * `LineChart`는 `aspectRatio` 속성을 비우면 인라인 크기를 정하지 않고 부모를 채운다. 비율을 CSS에
+ * 두어야 화면 폭에 따라 미디어 쿼리로 바꿀 수 있다.
+ */
+.canvas {
+  height: 100%;
+}
+
+.notes {
+  margin: 0;
+  color: var(--thorp-copy);
+  font-size: 0.85rem;
+  line-height: 1.6;
+  overflow-wrap: anywhere;
+}
+
+@media (max-width: 600px) {
+  .chart {
+    aspect-ratio: 4 / 3;
+  }
+}

